#include <iostream>
#include <memory>
#include <string>
#include <string_view>
#include <vector>
#include <cmath>

// ============================================================
// S — Single Responsibility
// ============================================================
struct Employee { std::string name; double salary; };

// Separate classes for separate concerns
class PayrollCalculator {
public:
    double compute(const Employee& e) const {
        return e.salary * 12.0;   // reason to change: payroll rules
    }
};

class EmployeeReport {
public:
    void print(const Employee& e, double annual) const {
        // reason to change: report format
        std::cout << "  " << e.name << " — annual: $" << annual << "\n";
    }
};

// ============================================================
// O — Open/Closed
// ============================================================
struct Shape {
    virtual double area() const = 0;
    virtual std::string_view kind() const = 0;
    virtual ~Shape() = default;
};

struct Circle : Shape {
    double r;
    explicit Circle(double r) : r(r) {}
    double area() const override { return M_PI * r * r; }
    std::string_view kind() const override { return "Circle"; }
};

struct Rect : Shape {
    double w, h;
    Rect(double w, double h) : w(w), h(h) {}
    double area() const override { return w * h; }
    std::string_view kind() const override { return "Rectangle"; }
};

// totalArea never changes when new shapes are added
double totalArea(const std::vector<std::unique_ptr<Shape>>& shapes) {
    double sum = 0;
    for (const auto& s : shapes) sum += s->area();
    return sum;
}

// ============================================================
// L — Liskov Substitution
// ============================================================
// ❌ The classic Square-Rectangle violation is avoided by NOT inheriting
// Instead: separate value types
struct RectVal { double w, h; double area() const { return w * h; } };
struct SquareVal { double side; double area() const { return side * side; } };
// Both work independently — no LSP violation

// ============================================================
// I — Interface Segregation
// ============================================================
struct Readable  {
    virtual std::string read(std::string_view key) const = 0;
    virtual ~Readable() = default;
};
struct Writeable {
    virtual void write(std::string_view key, std::string val) = 0;
    virtual ~Writeable() = default;
};

// In-memory store: implements both interfaces
class MemoryStore : public Readable, public Writeable {
public:
    std::string read(std::string_view key) const override {
        auto it = data_.find(std::string(key));
        return (it != data_.end()) ? it->second : "";
    }
    void write(std::string_view key, std::string val) override {
        data_[std::string(key)] = std::move(val);
    }
private:
    std::map<std::string, std::string> data_;
};

// Read-only renderer only needs Readable — not coupled to write operations
void renderValue(const Readable& store, std::string_view key) {
    std::cout << "  " << key << " = " << store.read(key) << "\n";
}

// ============================================================
// D — Dependency Inversion
// ============================================================
struct Notifier {
    virtual void notify(std::string_view msg) = 0;
    virtual ~Notifier() = default;
};

struct ConsoleNotifier : Notifier {
    void notify(std::string_view msg) override {
        std::cout << "  [notify] " << msg << "\n";
    }
};

// OrderService depends on the Notifier abstraction — not on any concrete impl
class OrderService {
public:
    explicit OrderService(Notifier& notifier) : notifier_(notifier) {}

    void placeOrder(std::string_view item) {
        std::cout << "  Placing order for: " << item << "\n";
        notifier_.notify(std::string("Order placed: ") + std::string(item));
    }
private:
    Notifier& notifier_;   // ← depends on abstraction, not concrete type
};

// ============================================================
int main() {
    std::cout << "=== Day 18: SOLID Principles ===\n\n";

    // S — Single Responsibility
    std::cout << "[S] Single Responsibility\n";
    Employee emp{"Alice", 5000.0};
    PayrollCalculator calc;
    EmployeeReport report;
    report.print(emp, calc.compute(emp));

    // O — Open/Closed
    std::cout << "\n[O] Open/Closed\n";
    std::vector<std::unique_ptr<Shape>> shapes;
    shapes.push_back(std::make_unique<Circle>(3.0));
    shapes.push_back(std::make_unique<Rect>(4.0, 5.0));
    std::cout << "  Total area: " << totalArea(shapes) << "\n";

    // L — Liskov Substitution (composition avoids violation)
    std::cout << "\n[L] Liskov Substitution\n";
    RectVal  rv{4, 5};
    SquareVal sv{4};
    std::cout << "  Rect area: " << rv.area() << ", Square area: " << sv.area() << "\n";

    // I — Interface Segregation
    std::cout << "\n[I] Interface Segregation\n";
    MemoryStore store;
    store.write("theme", "dark");
    store.write("lang", "en");
    renderValue(store, "theme");   // only needs Readable
    renderValue(store, "lang");

    // D — Dependency Inversion
    std::cout << "\n[D] Dependency Inversion\n";
    ConsoleNotifier notifier;
    OrderService service(notifier);   // inject concrete impl via interface
    service.placeOrder("Modern C++ Book");

    return 0;
}
